CREATE TEMPORARY TABLE `_seed_ClassificationTests` LIKE `ClassificationTests`;
INSERT INTO `_seed_ClassificationTests` (`test_id`, `test_code`, `description`, `phase`, `test_kind`, `source_note`, `expected_defect_type_id`, `expected_element_type_id`, `expected_d`, `expected_c`, `expected_severity`, `tolerance_bands`, `is_active`, `created_at`) VALUES (1,'SURVEY-1','Hairline crack on a non-structural wall','construction','anchor','Survey: Inspector=moderate, Engr I=low',1,10,1,2,'low',1,1,'2026-10-15 08:59:24'),(2,'SURVEY-2','Wide crack on a concrete beam with work continuing below','construction','anchor','Survey: Inspector=critical, Engr I=high. Only critical in the set.',1,2,4,4,'critical',1,1,'2026-10-15 08:59:24'),(3,'SURVEY-3','Exposed reinforcement bar on a column','construction','anchor','Survey: both high.',3,1,2,4,'high',1,1,'2026-10-15 08:59:24'),(4,'SURVEY-4','Minor surface finishing defect','construction','anchor','Survey: both low.',6,14,1,1,'low',1,1,'2026-10-15 08:59:24'),(5,'SURVEY-5','Dimensional deviation exceeding the specified tolerance','construction','anchor','Survey: both moderate. No element stated.',4,12,3,2,'moderate',1,1,'2026-10-15 08:59:24'),(6,'SURVEY-6','Water leakage into a finished area','post_completion','anchor','Survey: both moderate.',7,12,3,2,'moderate',1,1,'2026-10-15 08:59:24'),(7,'SURVEY-7','Honeycombing found on a newly poured column','construction','anchor','Survey: both high.',2,1,2,4,'high',1,1,'2026-10-15 08:59:24'),(8,'SURVEY-8','Settlement observed near a completed structure','post_completion','anchor','Survey: Inspector=moderate, Engr I=high. THE AMBIGUOUS ONE: experts split here.',8,3,2,4,'high',1,1,'2026-10-15 08:59:24'),(16,'REG-01','Exposed rebar on a column, no corrosion yet','construction','regression','\"no corrosion\" is a condition phrase, not a negation',NULL,NULL,NULL,NULL,'high',0,1,'2026-10-15 08:59:24'),(17,'REG-02','No cracks observed, the surface is sound','construction','regression','negated defect: nothing found, routed to general path',NULL,NULL,NULL,NULL,'low',0,1,'2026-10-15 08:59:24'),(18,'REG-03','Noted crack at the beam soffit','construction','regression','\"noted\" must not be read as the negation \"not\"',NULL,NULL,NULL,NULL,'high',0,1,'2026-10-15 08:59:24'),(19,'REG-04','No leak. Wide crack on the beam.','construction','regression','a full stop ends the negation, so the crack survives',NULL,NULL,NULL,NULL,'critical',0,1,'2026-10-15 08:59:24'),(20,'REG-05','Hairline crack on the non-structural wall','construction','regression','\"non structural wall\" must not match \"structural wall\"',NULL,NULL,NULL,NULL,'low',0,1,'2026-10-15 08:59:24'),(21,'REG-06','May bitak sa haligi, deep','construction','regression','Taglish: bitak = crack, haligi = column, filler words dropped',NULL,NULL,NULL,NULL,'critical',0,1,'2026-10-15 08:59:24'),(22,'REG-07','Severe widespread extensive hairline cracking on partition','construction','regression','modifiers move D by one level at most',NULL,NULL,NULL,NULL,'low',0,1,'2026-10-15 08:59:24'),(23,'REG-08','Hairline crack on the partition, stop work','construction','regression','verdict far above the result: flagged for review, result unchanged',NULL,NULL,NULL,NULL,'low',0,1,'2026-10-15 08:59:24'),(24,'REG-09','Settlment near the foundation, progressive','post_completion','regression','typo \"settlment\" still matches settlement',NULL,NULL,NULL,NULL,'critical',0,1,'2026-10-15 08:59:24'),(25,'REG-10','Continuous leak through the ceiling of the occupied unit','post_completion','regression','exposure raises C by one',NULL,NULL,NULL,NULL,'high',0,1,'2026-10-15 08:59:24'),(26,'REG-11','Crack on the wall near the column','construction','regression','nearest element (wall) wins; the column is flagged, not silently used',NULL,NULL,NULL,NULL,'low',0,1,'2026-10-15 08:59:24'),(27,'REG-12','May tumutulo sa kisame','post_completion','regression','Tagalog: tumutulo = leak, kisame = ceiling',NULL,NULL,NULL,NULL,'low',0,1,'2026-10-15 08:59:24'),(28,'REG-13','Malakas ang tagas sa ceiling ng occupied unit','post_completion','regression','malakas raises D by one; occupied raises C by one',NULL,NULL,NULL,NULL,'high',0,1,'2026-10-15 08:59:24'),(29,'REG-14','Nakalitaw ang bakal sa haligi, may kalawang','construction','regression','Tagalog rebar name + rust (level 3) on a column',NULL,NULL,NULL,NULL,'critical',0,1,'2026-10-15 08:59:24'),(30,'REG-15','Localized reinforcement exposure on the beam','construction','regression','rebar has no level 1 in Table 4c: \"localized\" cannot push it below 2',NULL,NULL,NULL,NULL,'high',0,1,'2026-10-15 08:59:24'),(31,'REG-16','No leak observed, dampness on the wall only','post_completion','regression','\"observed\" is filler; the leak is negated, dampness (level 1) remains',NULL,NULL,NULL,NULL,'low',0,1,'2026-10-15 08:59:24'),(32,'REG-17','Walang kalawang, exposed ang bakal sa beam','construction','regression','Tagalog negation cancels the rust, not the exposed steel after the comma',NULL,NULL,NULL,NULL,'high',0,1,'2026-10-15 08:59:24'),(33,'REG-18','Crack on the beam, 0.2 mm wide','construction','regression','a measurement is not graded: \"wide\" after a number is set aside and flagged',NULL,NULL,NULL,NULL,'high',0,1,'2026-10-15 08:59:24'),(34,'REG-19','Exposed rebar at slab soffit, rusting, for NCR','construction','regression','rusting = surface corrosion (level 3) on a structural slab',NULL,NULL,NULL,NULL,'critical',0,1,'2026-10-15 08:59:24'),(47,'REG-20','Small crack on the column','construction','regression','size word lowers the default level by one (same as hairline)',NULL,NULL,NULL,NULL,'moderate',0,1,'2026-10-15 08:59:24'),(48,'REG-21','Malaking bitak sa haligi','construction','regression','Tagalog size word raises the default level by one (same as deep)',NULL,NULL,NULL,NULL,'critical',0,1,'2026-10-15 08:59:24'),(49,'REG-22','Column no 5 has a wide crack','construction','regression','\"no\" before a number means \"number\", not a negation',NULL,NULL,NULL,NULL,'critical',0,1,'2026-10-15 08:59:24'),(50,'REG-23','Rusty rebar on the beam','construction','regression','synonym: rusty = rust (level 3)',NULL,NULL,NULL,NULL,'critical',0,1,'2026-10-15 08:59:24'),(51,'REG-24','Crack on the lintel','construction','regression','synonym: a lintel is a beam (C4)',NULL,NULL,NULL,NULL,'high',0,1,'2026-10-15 08:59:24'),(52,'REG-25','Widening crack on the partition wall','construction','regression','synonym: widening = active (level 4)',NULL,NULL,NULL,NULL,'high',0,1,'2026-10-15 08:59:24'),(53,'REG-26','Deep crack on the stair, residents nearby','post_completion','regression','people at risk: residents raise C by one',NULL,NULL,NULL,NULL,'critical',0,1,'2026-10-15 08:59:24'),(54,'REG-27','Malalim na bitak sa biga','construction','regression','Tagalog: malalim = deep, biga = beam',NULL,NULL,NULL,NULL,'critical',0,1,'2026-10-15 08:59:24'),(55,'REG-28','No of wide cracks on the column: 3','construction','regression','\"no of\" means \"number of\", not a negation',NULL,NULL,NULL,NULL,'critical',0,1,'2026-10-15 08:59:24'),(56,'REG-29','Crack on the wall beside a 2 m wide opening','construction','regression','\"2 m wide\" is a measurement: \"wide\" is set aside and flagged',NULL,NULL,NULL,NULL,'low',0,1,'2026-10-15 08:59:24'),(57,'REG-30','Hairline crack near the pile of sand','construction','regression','\"pile\" alone is a heap, not a foundation; no element named = C2',NULL,NULL,NULL,NULL,'low',0,1,'2026-10-15 08:59:24'),(58,'REG-31','Crack on the pedestal lavatory','construction','regression','\"pedestal\" alone is a fixture, not a column',NULL,NULL,NULL,NULL,'low',0,1,'2026-10-15 08:59:24'),(59,'REG-32','Crack is getting wider on the column','construction','regression','synonym: getting wider = widening (level 4)',NULL,NULL,NULL,NULL,'critical',0,1,'2026-10-15 08:59:24');
INSERT INTO `ClassificationTests` SELECT * FROM `_seed_ClassificationTests`
 WHERE NOT EXISTS (SELECT 1 FROM `ClassificationTests` LIMIT 1);
DROP TEMPORARY TABLE `_seed_ClassificationTests`;

CREATE TEMPORARY TABLE `_seed_LexiconChangelog` LIKE `LexiconChangelog`;
INSERT INTO `_seed_LexiconChangelog` (`change_id`, `object_type`, `object_code`, `object_id`, `action`, `before_value`, `after_value`, `reason`, `source_citation`, `changed_by`, `changed_at`, `verified_by_run`) VALUES (1,'matrix','SeverityMatrix',NULL,'added',NULL,'16 D x C cells','Matrix assignment, not arithmetic product.','Cox, L. A., Jr. (2008). What\'s wrong with risk matrices? Risk Analysis, 28(2), 497-512.',NULL,'2026-10-15 08:59:24',NULL),(2,'lexicon_term','knowledge_base_v2',NULL,'added',NULL,'Criteria for all 10 defect types; vocabulary expanded; verdict cross-check terms','Settlement and dimensional deviation start at level 2 (team decision). Material non-conformance applies to both phases.','Paper Table 4c; team research file v2; ICRI Concrete Repair Terminology (2022)',NULL,'2026-10-15 08:59:24',NULL),(3,'lexicon_term','knowledge_base_v3',NULL,'added',NULL,'Water leakage and exposed rebar vocabulary, Tagalog terms, conclusion phrases; cover words moved from spalling to rebar','Team research file v3. Tagalog terms and inspector phrases are researcher-developed. Rebar keeps no level 1 (paper Table 4c).','Team research file v3; ICRI Concrete Repair Terminology (2022); ACI 364.6T-02(11)',NULL,'2026-10-15 08:59:24',NULL),(4,'lexicon_term','size_words_2026_09_30',NULL,'added',NULL,'big, large, huge, malaki, malaking (raise one level); small, tiny, maliit (lower one level)','Inspectors describe size in plain words; these were ignored. One step only, like major/minor.','Engine default; to be confirmed by the team',NULL,'2026-10-15 08:59:24',NULL),(5,'lexicon_term','synonyms_2026_09_30',NULL,'added',NULL,'Synonyms and variants of existing words (cracking, spalling, rebar, water, settlement, dimensional, material, workmanship, incomplete work, building parts, people at risk, conclusions)','Other wordings were not recognised and gave a wrong severity. Every row copies the meaning and level of an existing sourced word; no new defect type or level decision.','Engine default; ICRI Concrete Repair Terminology (2022); to be confirmed by the team',NULL,'2026-10-15 08:59:24',NULL);
INSERT INTO `LexiconChangelog` SELECT * FROM `_seed_LexiconChangelog`
 WHERE NOT EXISTS (SELECT 1 FROM `LexiconChangelog` LIMIT 1);
DROP TEMPORARY TABLE `_seed_LexiconChangelog`;

-- ── 3. New columns on existing tables ──

ALTER TABLE InspectionReports
  ADD COLUMN IF NOT EXISTS phase ENUM('construction','post_completion') NOT NULL DEFAULT 'construction' AFTER issue_type,
  ADD COLUMN IF NOT EXISTS defect_type_id INT UNSIGNED DEFAULT NULL AFTER phase,
  ADD COLUMN IF NOT EXISTS element_type_id INT UNSIGNED DEFAULT NULL AFTER defect_type_id,
  ADD COLUMN IF NOT EXISTS d_level TINYINT DEFAULT NULL AFTER element_type_id,
  ADD COLUMN IF NOT EXISTS c_level TINYINT DEFAULT NULL AFTER d_level,
  ADD COLUMN IF NOT EXISTS recommended_severity ENUM('low','moderate','high','critical') DEFAULT NULL AFTER c_level,
  ADD COLUMN IF NOT EXISTS classification_confidence TINYINT UNSIGNED DEFAULT NULL AFTER recommended_severity,
  ADD COLUMN IF NOT EXISTS matched_terms TEXT DEFAULT NULL AFTER classification_confidence,
  ADD COLUMN IF NOT EXISTS classification_notes TEXT DEFAULT NULL AFTER matched_terms,
  ADD COLUMN IF NOT EXISTS severity_overridden_by INT UNSIGNED DEFAULT NULL AFTER classification_notes,
  ADD COLUMN IF NOT EXISTS severity_overridden_at DATETIME DEFAULT NULL AFTER severity_overridden_by,
  ADD COLUMN IF NOT EXISTS address_text VARCHAR(255) DEFAULT NULL AFTER location_text,
  ADD COLUMN IF NOT EXISTS province_code CHAR(4) DEFAULT NULL AFTER address_text,
  ADD COLUMN IF NOT EXISTS city_code CHAR(6) DEFAULT NULL AFTER province_code,
  ADD COLUMN IF NOT EXISTS brgy_code CHAR(9) DEFAULT NULL AFTER city_code;

ALTER TABLE InspectionReports
  ADD CONSTRAINT fk_rep_defect   FOREIGN KEY IF NOT EXISTS (defect_type_id)
      REFERENCES DefectTypes(defect_type_id) ON DELETE SET NULL,
  ADD CONSTRAINT fk_rep_element  FOREIGN KEY IF NOT EXISTS (element_type_id)
      REFERENCES ElementTypes(element_type_id) ON DELETE SET NULL,
  ADD CONSTRAINT fk_rep_override FOREIGN KEY IF NOT EXISTS (severity_overridden_by)
      REFERENCES Users(user_id) ON DELETE SET NULL;

-- Three-stage verification: new statuses (existing values are kept).
ALTER TABLE WorkOrders
  MODIFY COLUMN status ENUM('pending','in_progress','on_hold','pending_supervisor','pending_inspector','pending_closure','rework','completed') NOT NULL DEFAULT 'pending',
  ADD COLUMN IF NOT EXISTS verify_inspector_id INT UNSIGNED DEFAULT NULL AFTER status,
  ADD COLUMN IF NOT EXISTS supervisor_verified_by INT UNSIGNED DEFAULT NULL AFTER verify_inspector_id,
  ADD COLUMN IF NOT EXISTS supervisor_verified_at DATETIME DEFAULT NULL AFTER supervisor_verified_by,
  ADD COLUMN IF NOT EXISTS inspector_verified_by INT UNSIGNED DEFAULT NULL AFTER supervisor_verified_at,
  ADD COLUMN IF NOT EXISTS inspector_verified_at DATETIME DEFAULT NULL AFTER inspector_verified_by,
  ADD COLUMN IF NOT EXISTS closed_by INT UNSIGNED DEFAULT NULL AFTER inspector_verified_at,
  ADD COLUMN IF NOT EXISTS closed_at DATETIME DEFAULT NULL AFTER closed_by;

ALTER TABLE WorkOrders
  ADD CONSTRAINT fk_wo_verify_insp FOREIGN KEY IF NOT EXISTS (verify_inspector_id)
      REFERENCES Users(user_id) ON DELETE SET NULL,
  ADD CONSTRAINT fk_wo_sup_verify  FOREIGN KEY IF NOT EXISTS (supervisor_verified_by)
      REFERENCES Users(user_id) ON DELETE SET NULL,
  ADD CONSTRAINT fk_wo_insp_verify FOREIGN KEY IF NOT EXISTS (inspector_verified_by)
      REFERENCES Users(user_id) ON DELETE SET NULL,
  ADD CONSTRAINT fk_wo_closed_by   FOREIGN KEY IF NOT EXISTS (closed_by)
      REFERENCES Users(user_id) ON DELETE SET NULL;

ALTER TABLE FieldWorkUpdates
  MODIFY COLUMN status ENUM('in_progress','on_hold','completed','pending_supervisor','pending_inspector','pending_closure','rework') NOT NULL;

-- Contact number, collected at sign-up from now on. Existing accounts
-- start without one and can add it from My Profile.
ALTER TABLE Users
  ADD COLUMN IF NOT EXISTS contact_number VARCHAR(20) DEFAULT NULL AFTER address;
ALTER TABLE PendingRegistrations
  ADD COLUMN IF NOT EXISTS contact_number VARCHAR(20) DEFAULT NULL AFTER address;

-- A task that is no longer needed can be cancelled before it is inspected.
ALTER TABLE InspectionTasks
  MODIFY COLUMN status ENUM('assigned','submitted','closed','cancelled') NOT NULL DEFAULT 'assigned';

-- The activity log is sealed (config/logseal.php). Entries already there
-- are sealed as they stand the first time the log is written to or checked.
ALTER TABLE ActivityLogs
  ADD COLUMN IF NOT EXISTS chain_seq INT UNSIGNED DEFAULT NULL,
  ADD COLUMN IF NOT EXISTS prev_hash CHAR(64)     DEFAULT NULL,
  ADD COLUMN IF NOT EXISTS row_hash  CHAR(64)     DEFAULT NULL,
  ADD INDEX  IF NOT EXISTS idx_logs_chain (team_id, chain_seq);

CREATE TABLE IF NOT EXISTS LogChains (
  chain_key     INT UNSIGNED  NOT NULL PRIMARY KEY,
  length        INT UNSIGNED  NOT NULL,
  head_hash     CHAR(64)      NOT NULL,
  head_sig      CHAR(64)      NOT NULL,
  updated_at    DATETIME      NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB;

-- ── 4. Carry existing records over ──

-- Every work order now has a crew. Before this upgrade it had one
-- person in assigned_to; that person becomes the lead. Without this,
-- existing jobs would vanish from the field workers' queues.
INSERT INTO WorkOrderAssignees (wo_id, user_id, is_lead)
SELECT w.wo_id, w.assigned_to, 1
  FROM WorkOrders w
 WHERE w.assigned_to IS NOT NULL
   AND NOT EXISTS (SELECT 1 FROM WorkOrderAssignees a WHERE a.wo_id = w.wo_id);

-- Work orders completed before the verification stages existed have no
-- closing date; the summaries and the workload ranking count "closed"
-- by it. Their last update is the best record of when they finished.
UPDATE WorkOrders
   SET closed_at = updated_at,
       updated_at = updated_at     -- keep it: the column refreshes itself on any change
 WHERE status = 'completed' AND closed_at IS NULL;

-- ── 5. Review flag replaces the confidence score ──

-- The engine no longer scores confidence. Whether a report needs the
-- supervisor's review is stored with it instead. Reports filed before
-- this change keep the flag they were shown: confidence below 80%.
-- Then the confidence column itself is dropped. Section 3 still adds it,
-- because matched_terms is placed after it, so a second run adds it empty
-- and drops it again.
ALTER TABLE InspectionReports
  ADD COLUMN IF NOT EXISTS needs_review TINYINT(1) NOT NULL DEFAULT 0 AFTER recommended_severity;

UPDATE InspectionReports
   SET needs_review = 1,
       updated_at = updated_at     -- keep it: the column refreshes itself on any change
 WHERE classification_confidence < 80 AND needs_review = 0;

ALTER TABLE InspectionReports DROP COLUMN IF EXISTS classification_confidence;

-- ── 6. Negation scope and Tagalog negation words ──
-- ============================================================
-- Negation to the end of the clause; Tagalog "hindi" and "wala" (2026-10-26)
--
-- Safe to run twice. Needs the matching SeverityClassifier.php change
-- (negation scope), or REG-33 and REG-35 will fail.
-- ============================================================
